- [ ] **Step 8: Implement `useBackgroundLocation.ts`**

Create `tablet/src/hooks/useBackgroundLocation.ts`:

```typescript
import { useCallback, useRef, useState } from 'react'
import { BackgroundGeolocation } from '@capacitor-community/background-geolocation'
import { appendPing, getPings, type PingLogEntry } from '../lib/pingLog'

interface Location {
  latitude: number
  longitude: number
  accuracy: number
  time: number
}

interface WatcherError {
  code: string
}

interface UseBackgroundLocationResult {
  isTracking: boolean
  error: string | null
  pingCount: number
  start: () => Promise<void>
  stop: () => Promise<void>
}

export function useBackgroundLocation(): UseBackgroundLocationResult {
  const [isTracking, setIsTracking] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [pingCount, setPingCount] = useState<number>(() => getPings().length)
  const watcherIdRef = useRef<string | null>(null)

  const start = useCallback(async () => {
    setError(null)
    const id = await BackgroundGeolocation.addWatcher(
      {
        backgroundTitle: 'Atlas Field Force',
        backgroundMessage: 'Tracking your location for the field-force spike',
        requestPermissions: true,
        stale: false,
        distanceFilter: 0,
      },
      (location: Location | null, watcherError: WatcherError | null) => {
        if (watcherError) {
          setError(watcherError.code)
          return
        }
        if (location) {
          const entry: PingLogEntry = {
            latitude: location.latitude,
            longitude: location.longitude,
            accuracy: location.accuracy,
            time: location.time,
          }
          appendPing(entry)
          setPingCount(getPings().length)
        }
      },
    )
    watcherIdRef.current = id
    setIsTracking(true)
  }, [])

  const stop = useCallback(async () => {
    if (watcherIdRef.current) {
      await BackgroundGeolocation.removeWatcher({ id: watcherIdRef.current })
      watcherIdRef.current = null
    }
    setIsTracking(false)
  }, [])

  return { isTracking, error, pingCount, start, stop }
}
```

