- [ ] **Step 10: Build the spike screen UI**

Replace `tablet/src/App.tsx`:

```tsx
import { useState } from 'react'
import { useBackgroundLocation } from './hooks/useBackgroundLocation'
import { getPings, clearPings } from './lib/pingLog'

function App() {
  const { isTracking, error, pingCount, start, stop } = useBackgroundLocation()
  const [showLog, setShowLog] = useState(false)

  return (
    <div className="p-6 max-w-md mx-auto font-sans">
      <h1 className="text-xl font-bold mb-4">Field Force — Location Spike</h1>

      <div className="mb-4">
        <span className="font-semibold">Status: </span>
        {isTracking ? 'Tracking' : 'Stopped'}
      </div>

      {error && (
        <div className="mb-4 text-red-600">Error: {error}</div>
      )}

      <div className="mb-4">
        <span className="font-semibold">Pings logged: </span>
        {pingCount}
      </div>

      <div className="flex gap-2 mb-6">
        <button
          onClick={() => void start()}
          disabled={isTracking}
          className="px-4 py-2 bg-blue-600 text-white rounded disabled:opacity-40"
        >
          Start
        </button>
        <button
          onClick={() => void stop()}
          disabled={!isTracking}
          className="px-4 py-2 bg-gray-600 text-white rounded disabled:opacity-40"
        >
          Stop
        </button>
        <button
          onClick={() => setShowLog((v) => !v)}
          className="px-4 py-2 bg-gray-200 rounded"
        >
          {showLog ? 'Hide log' : 'Show log'}
        </button>
        <button
          onClick={() => clearPings()}
          className="px-4 py-2 bg-gray-200 rounded"
        >
          Clear
        </button>
      </div>

      {showLog && (
        <ul className="text-xs font-mono space-y-1 max-h-96 overflow-y-auto">
          {getPings().slice(-50).reverse().map((p, i) => (
            <li key={i}>
              {new Date(p.time).toISOString()} — {p.latitude.toFixed(5)}, {p.longitude.toFixed(5)} (±{p.accuracy.toFixed(0)}m)
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

export default App
```

- [ ] **Step 11: Add the Android manifest permissions**

Open `tablet/android/app/src/main/AndroidManifest.xml`. Inside the `<manifest>` element, above `<application>`, add (if not already present from the plugin's own Gradle setup — check first, don't duplicate):

```xml
    <uses-permission android:name="android.permission.ACCESS_FINE_LOCATION" />
    <uses-permission android:name="android.permission.ACCESS_COARSE_LOCATION" />
    <uses-permission android:name="android.permission.POST_NOTIFICATIONS" />
```

- [ ] **Step 12: Rebuild the web bundle and sync into the Android project**

```bash
npm run build
npx cap sync android
```

Expected: `Sync finished` with no errors, and the plugin's native Android sources appear under `android/app/src/main/java` (via the Gradle dependency, not copied files).

- [ ] **Step 13: Run the full test suite and verify everything passes**

```bash
npm run typecheck
npm run test
```

Expected: both exit 0; `test` shows all `pingLog` + `useBackgroundLocation` tests passing.

- [ ] **Step 14: Commit and open the PR**

```bash
cd ~/Documents/atlas-erp
git add tablet
git commit -m "feat(fieldforce): background-location watcher hook + spike screen

Wires @capacitor-community/background-geolocation behind a testable
hook (useBackgroundLocation) and a minimal screen that starts/stops
tracking and persists every fix to localStorage via pingLog, so a
human can background/lock the device and later inspect what arrived.
This is the spike itself — Task 4 runs it on real hardware.

Refs PLAN 18.1, design-spec §8."
git push -u origin feat/fieldforce-tablet-location-spike
gh pr create --base dev --title "feat(fieldforce): background-location watcher hook + spike screen" --body "$(cat <<'EOF'
## Summary
Adds the background-location watcher (via
@capacitor-community/background-geolocation) and a spike UI to
start/stop tracking and inspect logged fixes, ahead of running the
on-device verification protocol in Task 4 of the tablet-spike plan.

## Design notes
Fix persistence goes through localStorage (pingLog.ts) rather than
component state, specifically so fixes survive an app kill/restart —
the scenario this spike needs to observe.

## Invariants enforced
None — no server-side effects yet, this is client-only.

## Tests
5 tests in pingLog.test.ts, 5 in useBackgroundLocation.test.ts
(watcher mocked — real OS background behavior is NOT unit-testable
and is covered by the manual protocol in Task 4 instead).

## Linked items
Refs PLAN 18.1.

## Out of scope
Posting pings to the backend (Slice A backend doesn't exist yet) —
this spike only proves fixes keep arriving while backgrounded.
EOF
)"
gh pr checks <PR_NUMBER>
gh pr merge <PR_NUMBER> --squash --delete-branch
```

